public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        // Swap the current element with each element after it
        for (int j = i + 1; j < nums.length; j++) {
            swap(nums, i, j);
        }
        // Recursively permutate the rest of the array
        permute(nums, i + 1, result);
        // Swap the current element back with each element after it
        for (int j = i + 1; j < nums.length; j++) {
            swap(nums, i, j);
        }
    }
    return result;
}

private void permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.asList(nums));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}
