public class Permute {
    public List<List<Integer>> permute(int[] nums) {
        if (nums.length == 1) {
            List<List<Integer>> result = new ArrayList<>();
            List<Integer> list = new ArrayList<>();
            list.add(nums[0]);
            result.add(list);
            return result;
        }
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int[] remaining = Arrays.copyOfRange(nums, 0, i)
                    .concat(Arrays.copyOfRange(nums, i + 1, nums.length))
                    .toArray(new int[nums.length - 1]);
            for (List<Integer> perm : permute(remaining)) {
                List<Integer> next = new ArrayList<>();
                next.add(num);
                next.addAll(perm);
                result.add(next);
            }
        }
        return result;
    }
}
