private void permute(int[] nums, int start, List<Integer> current, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        permute(nums, i + 1, current, result);
        current.remove(current.size() - 1);
    }
}
