public int findLargestSubstring(List<String> strings) {
    // Sort the strings by their length in descending order
    List<String> sortedStrings = strings.stream()
            .sorted((s1, s2) -> s2.length() - s1.length())
            .collect(Collectors.toList());

    // Iterate over the sorted strings and find the first occurrence of a substring
    // that can be either the original string or its inverse
    for (String string : sortedStrings) {
        for (int i = 0; i < string.length(); i++) {
            String substring = string.substring(i);
            boolean found = false;
            for (String otherString : strings) {
                if (otherString.contains(substring)) {
                    found = true;
                    break;
                }
            }
            if (found) {
                return substring.length();
            }
        }
    }

    // If no such substring is found, return 0
    return 0;
}

