package org.waveapi;

import java.util.Arrays;
import java.util.Objects;

public class Utils {
    /**
     * Calculates the approximate value as a reduced fraction of up to 32 numerators and denominators of 32 bits.
     *
     * @param word1 The first word.
     * @param word2 The second word.
     * @return The approximate value as a reduced fraction as a string.
     */
    public static String appx(String word1, String word2) {
        Objects.requireNonNull(word1, "word1 is null");
        Objects.requireNonNull(word2, "word2 is null");
        if (word1.equals(word2)) {
            return "1";
        }
        int[] numerators = new int[32];
        int[] denominators = new int[32];
        int i = 0;
        for (char c : word1.toCharArray()) {
            numerators[i++] = c - 'A' + 1;
        }
        i = 0;
        for (char c : word2.toCharArray()) {
            denominators[i++] = c - 'A' + 1;
        }
        Arrays.sort(numerators);
        Arrays.sort(denominators);
        for (i = 0; i < numerators.length; i++) {
            int idx = Arrays.binarySearch(denominators, numerators[i]);
            if (idx >= 0) {
                numerators[i] = 0;
                denominators[idx] = 0;
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(word1).append(" ").append(word2).append(" = 0/0");
        for (i = 0; i < numerators.length; i++) {
            if (numerators[i] != 0) {
                sb.append(" / ").append(i + 1).append("!").append(numerators[i]);
            }
        }
        for (i = 0; i < denominators.length; i++) {
            if (denominators[i] != 0) {
                sb.append(" x ").append(i + 1).append("!").append(denominators[i]);
            }
        }
        return sb.toString();
    }
}
