public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the distance of each node from node 0
    int[][] distances = new int[n][n];
    for (int[] distance : distances) {
        Arrays.fill(distance, -1);
    }
    distances[0][0] = 0;

    // Initialize a queue to store the nodes to be visited
    Queue<Node> queue = new LinkedList<>();
    queue.add(new Node(0, 0));

    // Loop until all nodes are visited
    while (!queue.isEmpty()) {
        Node currentNode = queue.remove();
        int currentDistance = distances[0][currentNode.id];

        // If the current node has an apple, we can return to node 0 after visiting it
        if (hasApple[currentNode.id]) {
            return currentDistance;
        }

        // Iterate over the neighbors of the current node
        for (int neighborId : edges[currentNode.id]) {
            // If the neighbor is not yet visited, add it to the queue and set its distance to the current distance plus 1
            if (distances[0][neighborId] == -1) {
                queue.add(new Node(neighborId, currentDistance + 1));
                distances[0][neighborId] = currentDistance + 1;
            }
        }
    }
    return -1;
}

