public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;

    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 0;

                // horizontal line
                for (int k = j; k < n && mat[i][k] == 1; k++) {
                    length++;
                }

                // diagonal line from top left to bottom right
                for (int k = i; k < m && k < j && mat[k][j - k] == 1; k++) {
                    length++;
                }

                // diagonal line from top right to bottom left
                for (int k = i; k < m && k > j && mat[k][j + k] == 1; k++) {
                    length++;
                }

                maxLength = Math.max(maxLength, length);
            }
        }
    }

    return maxLength;
}
