public class Solution {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        boolean[] used = new boolean[n];
        int count = 0;

        permute(A, used, 0, n);

        return count;
    }

    private static void permute(int[] A, boolean[] used, int start, int n) {
        if (start == n) {
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!used[i] && (i == 0 || A[i - 1] != A[i]) && isSquare(A[i - 1] + A[i])) {
                used[i] = true;
                permute(A, used, start + 1, n);
                used[i] = false;
            }
        }
    }

    private static boolean isSquare(int x) {
        int y = (int) Math.sqrt(x);
        return x == y * y;
    }
}
