public static int findSmallestInteger(int n) {
    n = Math.abs(n); // Ensure n is positive

    // Get the list of digits of n in an array
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Find the smallest integer greater than n that can be formed by rearranging its digits
    int smallest = -1;
    for (int i = 9; i >= 0; i--) {
        while (digits[i] > 0) {
            int num = i;
            for (int j = 9; j > i; j--) {
                num = num * 10 + digits[j];
            }
            if (num > n && (smallest == -1 || num < smallest)) {
                smallest = num;
            }
            digits[i]--;
        }
    }

    return smallest;
