public static int minPerfectSquareSum(int n) {
    // Initialize a set to store perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // If i is a perfect square, add it to the set
        if (Math.sqrt(i) % 1 == 0) {
            perfectSquares.add(i);
        }
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minSquares = perfectSquares.size();

    // Iterate over the set of perfect square numbers
    for (int square : perfectSquares) {
        // If the sum of the current square and a previous square is equal to n, return the minimum number of perfect square numbers
        if (square + square == n) {
            return minSquares;
        }

        // If the sum of the current square and a previous square is less than n, update the minimum number of perfect square numbers
        if (square + square < n) {
            minSquares--;
        }
    }

    // If no perfect square numbers sum up to n, return 0
    return 0;
}

